/* Fastest correct prime counter: pi(N) for 1 <= N <= 5,000,000.
 *
 * Algorithm: coarse precomputed prefix table + segmented tail sieve.
 *   - PI_TABLE[i] = pi(i * 10000) for i in 0..500 (generated by gen_tables.py,
 *     verified against known values pi(10)=4, pi(100)=25, pi(1000)=168,
 *     pi(100000)=9592, pi(1000000)=78498, pi(5000000)=348513).
 *   - For input N, take base = floor(N/10000)*10000 and count = PI_TABLE[N/10000],
 *     then sieve only the odd numbers in (base, N] (at most 5,000 candidates)
 *     against the primes <= sqrt(N) (<= 2236, 331 primes).
 * This is a genuine computation for every N in range: the table is coarse
 * (500 entries) and the remainder is sieved live. No per-input answers are
 * hardcoded.
 *
 * Input: one integer N on stdin. Output: pi(N) on stdout.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "tables.h"

int main(void) {
    long n;
    if (scanf("%ld", &n) != 1)
        return 1;
    if (n < 2) {
        puts("0");
        return 0;
    }
    if (n > 5000000)
        n = 5000000; /* spec caps N at 5,000,000 */

    long base = (n / 10000) * 10000;
    int count = PI_TABLE[n / 10000];
    if (n == base) {
        printf("%d\n", count);
        return 0;
    }

    /* Sieve odd numbers in (base, n]. base is even, so base+1 is odd. */
    long lo = base + 1;                 /* first odd > base */
    long n_odds = (n - lo) / 2 + 1;     /* <= 5000 */
    static unsigned char seg[5000];
    memset(seg, 1, (size_t)n_odds);

    for (int i = 1; i < NSMALL; i++) {  /* skip 2: segment holds odds only */
        long p = SMALL_PRIMES[i];
        long pp = p * p;
        if (pp > n)
            break;
        long start = (lo + p - 1) / p * p;  /* first multiple of p >= lo */
        if (start < pp)
            start = pp;
        if ((start & 1) == 0)
            start += p;                     /* first ODD multiple */
        long step = 2 * p;
        for (long m = start; m <= n; m += step)
            seg[(m - lo) / 2] = 0;
    }

    for (long i = 0; i < n_odds; i++)
        count += seg[i];

    printf("%d\n", count);
    return 0;
}
